321		}
322		if elapsed := time.Since(start); elapsed > 5*time.Second {
323			t.Fatalf("resolveRepoCellPlacement waited %s; the lookup is not bounded", elapsed)
324		}
325		// Reported as a timeout, not as a missing mirror — the whole point is that
326		// the user looks at the control plane rather than at their mirrors.
327		if !strings.Contains(err.Error(), "timed out") {
