16	
17	// usCellAPIURL and usClusterSlug mirror the real aws-us-east-2 cell that
18	// entirehq/entire.io's processing placement lives on in prod, so the
19	// multi-homed regression tests below reproduce the actual bug rather than an
20	// invented topology.
21	const (
22		usCellAPIURL  = "https://aws-us-east-2.api.entire.io"
23		usClusterSlug = "aws-us-east-2"
24	
25		euClusterSlug          = euWestCell
26		apSoutheastClusterSlug = "aws-ap-southeast-1"
27		apSouthClusterSlug     = "aws-ap-south-1"
28	)
29	
30	func TestMatchClusterByHost(t *testing.T) {
31		t.Parallel()
32		clusters := []coreapi.Cluster{
33			{PublicUrl: "https://us.entire.io", Jurisdiction: "us", ApiUrl: coreapi.NewOptString("https://aws-us-east-2.api.entire.io")},
34			{PublicUrl: "https://eu.entire.io", Jurisdiction: "eu", ApiUrl: coreapi.NewOptString("https://aws-eu-west-1.api.entire.io")},
35		}
36	
37		// Match is on the public host, case-insensitive.
38		cl, ok := matchClusterByHost(clusters, "EU.entire.io")
39		if !ok {
40			t.Fatal("expected a match for eu.entire.io")
41		}
42		if cl.Jurisdiction != "eu" || cl.ApiUrl.Or("") != "https://aws-eu-west-1.api.entire.io" {
43			t.Fatalf("matched wrong cluster: %+v", cl)
44		}
45	
46		if _, ok := matchClusterByHost(clusters, "ap.entire.io"); ok {
47			t.Fatal("expected no match for unknown host")
48		}
49		if _, ok := matchClusterByHost(clusters, ""); ok {
50			t.Fatal("expected no match for empty host")
51		}
52	}
53	
54	// TestMatchClusterBySlug mirrors TestMatchClusterByHost for the slug-keyed
55	// join used by the processing-placement path: the catalog's Slug, not its
56	// PublicUrl host, is the reliable join key for a RepoPlacement.
57	func TestMatchClusterBySlug(t *testing.T) {
58		t.Parallel()
59		clusters := clustersWithSlugs()
60	
61		cl, ok := matchClusterBySlug(clusters, usClusterSlug)
62		if !ok {
63			t.Fatalf("expected a match for %s", usClusterSlug)
64		}
65		if cl.Jurisdiction != "us" || cl.ApiUrl.Or("") != usCellAPIURL {
66			t.Fatalf("matched wrong cluster: %+v", cl)
