409				withFakeCellCore(t, &fakeCellCore{repos: tc.repos, reposErr: tc.reposErr, clusters: tc.clusters, clustersErr: tc.clustersErr})
410				if _, err := resolveRepoCellPlacement(context.Background(), "acme", "widget"); err == nil {
411					t.Fatal("expected an error")
