417	// Bugbot (PR #1942): cross-repo reads must take the repo_id and the cell from
418	// the SAME placement. A mirror id is only resolvable by the cell holding that
419	// placement, so pairing one placement's id with a cell picked another way
420	// asks a cell about an id it has never seen. With a single placement this is
421	// trivially true; TestResolveRepoCellPlacement_MultiHomedRepo_ResolvesProcessingPlacement
422	// below is the version of this invariant that actually exercises a choice.
423	func TestResolveRepoCellPlacement_PairsIDWithItsOwnCell(t *testing.T) {
424		withFakeCellCore(t, &fakeCellCore{
425			repos: reposOutput(repoIndexFixture("acme/widget", "mirror-eu",
426				placementFixture{id: "mirror-eu", slug: euClusterSlug},
427			)),
428			clusters: clustersWithSlugs(),
429		})
430		got, err := resolveRepoCellPlacement(context.Background(), "acme", "widget")
431		if err != nil {
432			t.Fatalf("resolveRepoCellPlacement: %v", err)
433		}
434		if got.RepoID != "mirror-eu" {
435			t.Errorf("RepoID = %q, want mirror-eu", got.RepoID)
436		}
437		if got.Target == nil || got.Target.Jurisdiction != "eu" || got.Target.BaseURL != euCellAPIURL {
438			t.Fatalf("Target = %+v, want the eu cell that holds mirror-eu", got.Target)
439		}
