442	// A multi-homed repo must resolve to its PROCESSING placement specifically,
443	// not merely "some" placement (the pre-fix behavior in resolveRepoCellTarget
444	// was to refuse; resolveRepoCellPlacement's pre-fix behavior was to take
445	// whichever active mirror came first). The fixture orders the processing
446	// placement (mirror-us) last, so a resolver that still picked "first active"
447	// would fail this test.
448	func TestResolveRepoCellPlacement_MultiHomedRepo_ResolvesProcessingPlacement(t *testing.T) {
449		withFakeCellCore(t, &fakeCellCore{
450			repos:    reposOutput(fourRegionFixture()),
451			clusters: clustersWithSlugs(),
452		})
453		got, err := resolveRepoCellPlacement(context.Background(), "entirehq", "entire.io")
454		if err != nil {
455			t.Fatalf("resolveRepoCellPlacement: %v", err)
456		}
457		if got.RepoID != "mirror-us" {
458			t.Errorf("RepoID = %q, want mirror-us (the processing placement, not the first-listed one)", got.RepoID)
459		}
460		if got.Target == nil || got.Target.Jurisdiction != "us" || got.Target.BaseURL != usCellAPIURL {
461			t.Fatalf("Target = %+v, want the us cell that holds mirror-us", got.Target)
462		}
463	}
464	
465	// Trail #1003 finding: resolveRepoCellPlacement was the one cell-resolution
466	// entry point with no deadline, and the coreapi HTTP client sets only a dial
467	// timeout — so a reachable-but-slow control plane stalled `explain --repo`
468	// indefinitely, before its spinner had even started. The parent deadline here
469	// is shorter than requiredCellResolveTimeout, which is what keeps this test
470	// fast; the point is that the wait is bounded and reported as a timeout. The
471	// blocking now happens on ListRepos (the processing-placement lookup), not
472	// ListMirrors.
473	func TestResolveRepoCellPlacement_BoundedByDeadline(t *testing.T) {
474		withFakeCellCore(t, &fakeCellCore{blockUntilCtxDone: true, clusters: clustersWithSlugs()})
475	
476		ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
477		defer cancel()
478	
479		start := time.Now()
480		_, err := resolveRepoCellPlacement(ctx, "acme", "widget")
481		if err == nil {
482			t.Fatal("expected a timeout error from a stalled control plane")
483		}
484		if elapsed := time.Since(start); elapsed > 5*time.Second {
485			t.Fatalf("resolveRepoCellPlacement waited %s; the lookup is not bounded", elapsed)
486		}
487		// Reported as a timeout, not as a missing mirror — the whole point is that
488		// the user looks at the control plane rather than at their mirrors.
489		if !strings.Contains(err.Error(), "timed out") {
490			t.Errorf("error = %q, want it to name a timeout", err)
491		}
492		if !errors.Is(err, context.DeadlineExceeded) {
493			t.Errorf("error = %q, want it to wrap context.DeadlineExceeded", err)
494		}
495	}
496	
497	// The command cannot proceed without this lookup, so its budget is separate
498	// from the best-effort one that silently degrades to home-jurisdiction routing.
499	func TestRequiredCellResolveTimeoutIsItsOwnBudget(t *testing.T) {
500		t.Parallel()
501	
502		if requiredCellResolveTimeout <= cellResolveTimeout {
503			t.Errorf("requiredCellResolveTimeout (%s) should be more patient than the best-effort cellResolveTimeout (%s): a timeout here fails the command instead of degrading",
504				requiredCellResolveTimeout, cellResolveTimeout)
505		}
506	}
