		return
	}

	client, err := NewAuthenticatedAPIClient(ctx, insecureHTTPAuth)   // used for BOTH ReportEnable AND the TrailsEnabled probe below
	if err != nil {
		logging.Debug(ctx, "skipping enable report", "error", err)
		return
	}

	if _, err := client.ReportEnable(ctx, cleanURL); err != nil {
