**`ReportEnable` (`POST /api/v1/cli/enable`) is deliberately NOT changed** — it records an account/onboarding-level event against the backend (see its doc comment: "so the web onboarding can reflect it") and returns App-installation metadata, not repo-scoped cell data. There's no `ListRepos`/processing-placement concept relevant to it, and it isn't in the coreapi (control-plane) spec either — it's a BFF-only endpoint. Only `TrailsEnabled` is the same repo-scoped-cell bug as Fix 1.

**Fix**: split the function into two independent concerns — reporting to the backend (existing behavior, unchanged, `NewAuthenticatedAPIClient`), and probing+caching trails enablement (routed through the cell via `trailRefreshAPIClient`, same seam as Fix 1). This split also makes the changed part unit-testable — today `reportRepoEnabled` calls `NewAuthenticatedAPIClient` first (for `ReportEnable`) and returns early on any auth failure, which in a test environment with no login would always short-circuit BEFORE reaching the `TrailsEnabled` call, making that half untestable without this split.

```go
func reportRepoEnabled(ctx context.Context, insecureHTTPAuth bool) {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()

	rawURL, err := gitremote.GetRemoteURL(ctx, "origin")
	if err != nil || strings.TrimSpace(rawURL) == "" {
		return
	}
	info, err := gitremote.ParseURL(rawURL)
	if err != nil {
		logging.Debug(ctx, "skipping enable report: unparseable origin remote", "error", err)
		return
	}
	if info.Forge == "" {
		if err := saveTrailsEnabledForRemote(ctx, info.Forge, info.Owner, info.Repo, false); err != nil {
			logging.Debug(ctx, "failed to cache trails enablement", "error", err)
		}
		return
	}

	reportEnableToBackend(ctx, insecureHTTPAuth, rawURL)
	probeAndCacheTrailsEnablement(ctx, insecureHTTPAuth, info)
}

// reportEnableToBackend tells the backend which repo was just enabled, purely
// for the web onboarding UI and the GitHub-App-reachability nudge. Best-effort
// and independent of the trails probe below: a failure here (not logged in,
// network error, backend rejects the URL) must not block that probe.
func reportEnableToBackend(ctx context.Context, insecureHTTPAuth bool, rawURL string) {
	cleanURL, err := cleanRemoteURLForReport(rawURL)
	if err != nil {
		logging.Debug(ctx, "skipping enable report: unparseable origin remote", "error", err)
		return
	}
	client, err := NewAuthenticatedAPIClient(ctx, insecureHTTPAuth)
	if err != nil {
		logging.Debug(ctx, "skipping enable report", "error", err)
		return
	}
	if _, err := client.ReportEnable(ctx, cleanURL); err != nil {
		logging.Debug(ctx, "enable report failed", "error", err)
	}
}

// probeAndCacheTrailsEnablement checks whether trails are enabled for the repo
// that was just enabled, and caches the decision. Routes through the entire-api
// cell that hosts THIS repo (trailRefreshAPIClient), not the data-API/BFF host:
// the BFF does not proxy /api/v1/trails/... for bearer callers (COR-666), so
// probing it via NewAuthenticatedAPIClient silently misreads as disabled.
func probeAndCacheTrailsEnablement(ctx context.Context, insecureHTTPAuth bool, info *gitremote.Info) {
	client, err := trailRefreshAPIClient(ctx, insecureHTTPAuth, info.Owner+"/"+info.Repo)
	if err != nil {
		logging.Debug(ctx, "trails enablement probe client unavailable", "error", err)
		return
	}
	enabled, err := client.TrailsEnabled(ctx, info.Forge, info.Owner, info.Repo)
	if err != nil {
		logging.Debug(ctx, "trails enablement probe failed", "error", err)
		return
	}
	if err := saveTrailsEnabledForRemote(ctx, info.Forge, info.Owner, info.Repo, enabled); err != nil {
		logging.Debug(ctx, "failed to cache trails enablement", "error", err)
	}
}
```
